const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const region = ee.Geometry.Rectangle([120, -10, 160, 10], null, false); // Western Pacific tropics (120E-160E, 10S-10N)
    const years = [1998, 2009];
    const band = 'precipitation'; // TRMM 3B43V7 band (mm/hr)
    const scale = 25000; // ~25 km to match coarse dataset and avoid timeout

    // Static water mask (mask land) using MODIS Land Cover: IGBP class 0 = Water
    const waterMask = ee.Image('MODIS/006/MCD12Q1/2016_01_01').select('LC_Type1').eq(0);

    async function yearMetrics(year) {
      let start = ee.Date.fromYMD(year, 1, 1);
      let end = start.advance(1, 'year');
      let col = ee.ImageCollection('TRMM/3B43V7').filterDate(start, end).filterBounds(region);
      let size = await col.size().getInfo();
      if (size === 0) {
        // Try widening the date window a bit to recover edge cases
        start = ee.Date.fromYMD(year, 1, 1).advance(-1, 'month');
        end = ee.Date.fromYMD(year, 1, 1).advance(13, 'month');
        col = ee.ImageCollection('TRMM/3B43V7').filterDate(start, end).filterBounds(region);
        size = await col.size().getInfo();
        if (size === 0) {
          return { status: 'C1', year, size: 0 };
        }
      }
      // Apply water mask
      const colMasked = col.map(img => img.updateMask(waterMask));
      const meanImg = colMasked.select(band).mean();

      // Count valid pixels
      const countDict = await meanImg.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).getInfo();
      const pixelCount = countDict ? countDict[band] : null;
      if (!pixelCount || pixelCount === 0) {
        return { status: 'C2', year, size, pixelCount: pixelCount || 0 };
      }

      // Mean rainfall rate (mm/hr)
      const meanDict = await meanImg.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).getInfo();
      const meanVal = meanDict ? meanDict[band] : null;

      if (meanVal === null || isNaN(meanVal) || meanVal < 0 || meanVal > 20) {
        return { status: 'C3', year, size, pixelCount, mean: meanVal };
      }

      return { status: 'OK', year, size, pixelCount, mean: meanVal };
    }

    const stats1998 = await yearMetrics(1998);
    const stats2009 = await yearMetrics(2009);

    // Print concise evidence
    console.log('Region: 120E-160E, 10S-10N (water-only mask), Scale: 25 km');
    const fmt = (v) => (v === null || v === undefined) ? 'null' : Number(v).toFixed(3);
    console.log(`1998 Images: ${stats1998.size || 0}`);
    console.log(`2009 Images: ${stats2009.size || 0}`);

    // Handle failure cases in priority order
    if (stats1998.status === 'C1' || stats2009.status === 'C1') {
      console.log('Reason: Empty Collection for at least one year.');
      console.log('C1');
      return;
    }
    if (stats1998.status === 'C2' || stats2009.status === 'C2') {
      console.log('Reason: No valid pixels after masking for at least one year.');
      console.log('C2');
      return;
    }
    if (stats1998.status === 'C3' || stats2009.status === 'C3') {
      console.log('Reason: Calculation failure (null/NaN/out-of-range).');
      console.log('C3');
      return;
    }

    // Successful stats
    console.log(`1998 Mean Rain Rate (mm/hr): ${fmt(stats1998.mean)}, Valid px: ${stats1998.pixelCount}`);
    console.log(`2009 Mean Rain Rate (mm/hr): ${fmt(stats2009.mean)}, Valid px: ${stats2009.pixelCount}`);

    // Determine increase
    const diff = stats2009.mean - stats1998.mean;
    console.log(`Difference (2009 - 1998) mm/hr: ${fmt(diff)}`);

    // Final Answer
    if (!isFinite(diff)) {
      console.log('C3');
    } else if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err.message || err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
